// Procedural sound design — no external audio assets, everything is synthesized.
export class SoundEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.musicGain = null;
    this.sfxGain = null;
    this.enabled = true;
    this.rainGain = null;
    this.started = false;
    this.step = 0;
    this.nextBeat = 0;
    this._timer = null;
    this._noise = null;
  }

  init() {
    if (this.ctx) return;
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = 0.72;
    this.master.connect(this.ctx.destination);
    this.musicGain = this.ctx.createGain();
    this.musicGain.gain.value = 0.3;
    this.musicGain.connect(this.master);
    this.sfxGain = this.ctx.createGain();
    this.sfxGain.gain.value = 0.85;
    this.sfxGain.connect(this.master);
    this._noise = this._makeNoise(2.5);
    this._startAmbience();
  }

  async resume() {
    this.init();
    if (this.ctx?.state === 'suspended') await this.ctx.resume();
    if (!this.started && this.ctx) {
      this.started = true;
      this.nextBeat = this.ctx.currentTime + 0.1;
      this._timer = setInterval(() => this._scheduleMusic(), 90);
    }
  }

  setEnabled(on) {
    this.enabled = on;
    if (this.master && this.ctx) {
      this.master.gain.setTargetAtTime(on ? 0.72 : 0, this.ctx.currentTime, 0.04);
    }
  }

  _makeNoise(seconds = 2) {
    const length = Math.floor(this.ctx.sampleRate * seconds);
    const buffer = this.ctx.createBuffer(1, length, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    let last = 0;
    for (let i = 0; i < length; i++) {
      const white = Math.random() * 2 - 1;
      last = last * 0.72 + white * 0.28;
      data[i] = last;
    }
    return buffer;
  }

  _startAmbience() {
    if (!this.ctx) return;
    const ctx = this.ctx;
    // Storm wash — filtered noise bed.
    const rain = ctx.createBufferSource();
    rain.buffer = this._noise;
    rain.loop = true;
    const hp = ctx.createBiquadFilter();
    hp.type = 'highpass';
    hp.frequency.value = 1400;
    const lp = ctx.createBiquadFilter();
    lp.type = 'lowpass';
    lp.frequency.value = 7200;
    this.rainGain = ctx.createGain();
    this.rainGain.gain.value = 0.022;
    rain.connect(hp).connect(lp).connect(this.rainGain).connect(this.musicGain);
    rain.start();
    // Low tension drone.
    const droneGain = ctx.createGain();
    droneGain.gain.value = 0.035;
    droneGain.connect(this.musicGain);
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 260;
    filter.Q.value = 3;
    filter.connect(droneGain);
    [55, 82.41, 110].forEach((freq, i) => {
      const osc = ctx.createOscillator();
      osc.type = i === 2 ? 'triangle' : 'sawtooth';
      osc.frequency.value = freq * (i === 1 ? 1.004 : 1.001);
      const g = ctx.createGain();
      g.gain.value = i === 2 ? 0.35 : 0.2;
      osc.connect(g).connect(filter);
      osc.start();
    });
    const lfo = ctx.createOscillator();
    lfo.frequency.value = 0.08;
    const lfoGain = ctx.createGain();
    lfoGain.gain.value = 100;
    lfo.connect(lfoGain).connect(filter.frequency);
    lfo.start();
  }

  _scheduleMusic() {
    if (!this.ctx || this.ctx.state !== 'running' || !this.enabled) return;
    const ctx = this.ctx;
    const bpm = 88;
    const beat = 60 / bpm;
    while (this.nextBeat < ctx.currentTime + 0.22) {
      this._playStep(this.step, this.nextBeat);
      this.nextBeat += beat / 2;
      this.step = (this.step + 1) % 16;
    }
  }

  _playStep(step, time) {
    const ctx = this.ctx;
    const s = step % 16;
    if (s === 0 || s === 6 || s === 10) this._taiko(time, s === 0 ? 0.4 : 0.19);
    if (s === 4 || s === 12) this._taiko(time, 0.14, 1.5);
    if (s % 4 === 2) this._hat(time);
    if ([0, 3, 8, 11].includes(s)) {
      const seq = [110, 130.81, 98, 123.47];
      this._bass(time, seq[Math.floor(s / 4)] * 0.5, step);
    }
    if (s === 0 && Math.floor(this.step / 16) % 4 === 1) {
      this._shimmer(time, 440);
    }
  }

  _taiko(t = this.ctx.currentTime, gain = 0.3, pitch = 1) {
    if (!this.ctx) return;
    const ctx = this.ctx;
    const osc = ctx.createOscillator();
    const g = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(112 * pitch, t);
    osc.frequency.exponentialRampToValueAtTime(44 * pitch, t + 0.16);
    g.gain.setValueAtTime(gain, t);
    g.gain.exponentialRampToValueAtTime(0.001, t + 0.3);
    osc.connect(g).connect(this.musicGain);
    osc.start(t);
    osc.stop(t + 0.32);
    const noise = ctx.createBufferSource();
    noise.buffer = this._noise;
    const nf = ctx.createBiquadFilter();
    nf.type = 'lowpass';
    nf.frequency.value = 380;
    const ng = ctx.createGain();
    ng.gain.setValueAtTime(gain * 0.35, t);
    ng.gain.exponentialRampToValueAtTime(0.001, t + 0.09);
    noise.connect(nf).connect(ng).connect(this.musicGain);
    noise.start(t);
    noise.stop(t + 0.1);
  }

  _hat(t) {
    const ctx = this.ctx;
    const noise = ctx.createBufferSource();
    noise.buffer = this._noise;
    const hp = ctx.createBiquadFilter();
    hp.type = 'highpass';
    hp.frequency.value = 8400;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.022, t);
    g.gain.exponentialRampToValueAtTime(0.0005, t + 0.035);
    noise.connect(hp).connect(g).connect(this.musicGain);
    noise.start(t, Math.random());
    noise.stop(t + 0.04);
  }

  _bass(t, freq, step) {
    const ctx = this.ctx;
    const osc = ctx.createOscillator();
    osc.type = 'triangle';
    osc.frequency.value = freq;
    const lp = ctx.createBiquadFilter();
    lp.type = 'lowpass';
    lp.frequency.value = 320;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.06, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.33);
    osc.connect(lp).connect(g).connect(this.musicGain);
    osc.start(t);
    osc.stop(t + 0.35);
  }

  _shimmer(t, freq) {
    const ctx = this.ctx;
    for (let i = 0; i < 3; i++) {
      const osc = ctx.createOscillator();
      osc.type = 'sine';
      osc.frequency.value = freq * (i + 1) * 1.5;
      const g = ctx.createGain();
      g.gain.setValueAtTime(0.0001, t);
      g.gain.linearRampToValueAtTime(0.012, t + 0.25);
      g.gain.exponentialRampToValueAtTime(0.0001, t + 2.2);
      osc.connect(g).connect(this.musicGain);
      osc.start(t);
      osc.stop(t + 2.3);
    }
  }

  // ── SFX ──────────────────────────────────────────────────────────
  whoosh(pan = 0) {
    if (!this.ctx || !this.enabled) return;
    const ctx = this.ctx, t = ctx.currentTime;
    const noise = ctx.createBufferSource();
    noise.buffer = this._noise;
    const bp = ctx.createBiquadFilter();
    bp.type = 'bandpass';
    bp.Q.value = 1.6;
    bp.frequency.setValueAtTime(480, t);
    bp.frequency.exponentialRampToValueAtTime(1800, t + 0.14);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(0.08, t + 0.025);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.22);
    const p = ctx.createStereoPanner();
    p.pan.value = pan;
    noise.connect(bp).connect(g).connect(p).connect(this.sfxGain);
    noise.start(t);
    noise.stop(t + 0.24);
  }

  hit(power = 1, blocked = false) {
    if (!this.ctx || !this.enabled) return;
    const ctx = this.ctx, t = ctx.currentTime;
    const noise = ctx.createBufferSource();
    noise.buffer = this._noise;
    const bp = ctx.createBiquadFilter();
    bp.type = blocked ? 'bandpass' : 'lowpass';
    bp.frequency.value = blocked ? 2200 : 520 + power * 300;
    bp.Q.value = blocked ? 4 : 0.8;
    const g = ctx.createGain();
    g.gain.setValueAtTime(blocked ? 0.16 : 0.28 + power * 0.08, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + (blocked ? 0.18 : 0.34));
    noise.connect(bp).connect(g).connect(this.sfxGain);
    noise.start(t);
    noise.stop(t + 0.36);
    if (!blocked) {
      const osc = ctx.createOscillator();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(94, t);
      osc.frequency.exponentialRampToValueAtTime(32, t + 0.22);
      const og = ctx.createGain();
      og.gain.setValueAtTime(0.4 + power * 0.12, t);
      og.gain.exponentialRampToValueAtTime(0.0001, t + 0.3);
      osc.connect(og).connect(this.sfxGain);
      osc.start(t);
      osc.stop(t + 0.32);
    }
  }

  block() {
    if (!this.ctx || !this.enabled) return;
    const ctx = this.ctx, t = ctx.currentTime;
    [1320, 1980, 2640].forEach((f, i) => {
      const osc = ctx.createOscillator();
      osc.type = 'triangle';
      osc.frequency.value = f;
      const g = ctx.createGain();
      g.gain.setValueAtTime(0.05 / (i + 1), t);
      g.gain.exponentialRampToValueAtTime(0.0001, t + 0.16);
      osc.connect(g).connect(this.sfxGain);
      osc.start(t);
      osc.stop(t + 0.18);
    });
  }

  charge(duration = 0.45, pitch = 220) {
    if (!this.ctx || !this.enabled) return;
    const ctx = this.ctx, t = ctx.currentTime;
    const osc = ctx.createOscillator();
    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(pitch, t);
    osc.frequency.exponentialRampToValueAtTime(pitch * 3.8, t + duration);
    const lp = ctx.createBiquadFilter();
    lp.type = 'lowpass';
    lp.frequency.setValueAtTime(400, t);
    lp.frequency.exponentialRampToValueAtTime(3600, t + duration);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(0.09, t + 0.05);
    g.gain.exponentialRampToValueAtTime(0.0001, t + duration + 0.08);
    osc.connect(lp).connect(g).connect(this.sfxGain);
    osc.start(t);
    osc.stop(t + duration + 0.1);
  }

  zap() {
    if (!this.ctx || !this.enabled) return;
    const ctx = this.ctx, t = ctx.currentTime;
    const osc = ctx.createOscillator();
    osc.type = 'square';
    osc.frequency.setValueAtTime(880, t);
    osc.frequency.exponentialRampToValueAtTime(110, t + 0.24);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.12, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.27);
    osc.connect(g).connect(this.sfxGain);
    osc.start(t);
    osc.stop(t + 0.28);
    this.hit(1.4);
  }

  thunder() {
    if (!this.ctx || !this.enabled) return;
    const ctx = this.ctx, t = ctx.currentTime + 0.3;
    const noise = ctx.createBufferSource();
    noise.buffer = this._noise;
    noise.loop = true;
    const lp = ctx.createBiquadFilter();
    lp.type = 'lowpass';
    lp.frequency.value = 240;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(0.22, t + 0.06);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 2.4);
    noise.connect(lp).connect(g).connect(this.musicGain);
    noise.start(t);
    noise.stop(t + 2.5);
  }

  bell() {
    if (!this.ctx || !this.enabled) return;
    const ctx = this.ctx, t = ctx.currentTime;
    [660, 990, 1320].forEach((f, i) => {
      const osc = ctx.createOscillator();
      osc.type = 'sine';
      osc.frequency.value = f;
      const g = ctx.createGain();
      g.gain.setValueAtTime(0.0001, t);
      g.gain.linearRampToValueAtTime(0.07 / (i + 1), t + 0.02);
      g.gain.exponentialRampToValueAtTime(0.0001, t + 1.2);
      osc.connect(g).connect(this.sfxGain);
      osc.start(t);
      osc.stop(t + 1.25);
    });
  }

  uiClick() {
    if (!this.ctx || !this.enabled) return;
    const ctx = this.ctx, t = ctx.currentTime;
    const osc = ctx.createOscillator();
    osc.type = 'triangle';
    osc.frequency.value = 720;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.05, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.08);
    osc.connect(g).connect(this.sfxGain);
    osc.start(t);
    osc.stop(t + 0.09);
  }

  ko() {
    if (!this.ctx || !this.enabled) return;
    this.charge(0.9, 90);
    const ctx = this.ctx, t = ctx.currentTime + 0.1;
    const osc = ctx.createOscillator();
    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(110, t);
    osc.frequency.exponentialRampToValueAtTime(26, t + 1.1);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.22, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 1.3);
    osc.connect(g).connect(this.sfxGain);
    osc.start(t);
    osc.stop(t + 1.35);
    this.thunder();
  }
}

import * as THREE from 'three'

const rand = (a = 0, b = 1) => a + Math.random() * (b - a)
const clamp = (v, a, b) => Math.max(a, Math.min(b, v))

function canvasTexture(w, h, draw) {
  const c = document.createElement('canvas')
  c.width = w; c.height = h
  draw(c.getContext('2d'), w, h)
  const tex = new THREE.CanvasTexture(c)
  tex.colorSpace = THREE.SRGBColorSpace
  tex.anisotropy = 8
  return tex
}

function radialGlowTexture() {
  return canvasTexture(256, 256, (ctx) => {
    const g = ctx.createRadialGradient(128, 128, 0, 128, 128, 128)
    g.addColorStop(0, 'rgba(255,255,255,1)')
    g.addColorStop(.16, 'rgba(255,255,255,.7)')
    g.addColorStop(.42, 'rgba(255,255,255,.18)')
    g.addColorStop(1, 'rgba(255,255,255,0)')
    ctx.fillStyle = g
    ctx.fillRect(0, 0, 256, 256)
  })
}

function windowTexture() {
  return canvasTexture(128, 256, (ctx, w, h) => {
    ctx.fillStyle = '#080b13'
    ctx.fillRect(0, 0, w, h)
    for (let y = 8; y < h - 8; y += 13) {
      for (let x = 5; x < w - 5; x += 11) {
        if (Math.random() < .33) {
          const colors = ['#7dcbff', '#ffbd76', '#a48cff', '#ff6d55', '#9ce9d6']
          ctx.fillStyle = colors[Math.floor(Math.random() * colors.length)]
          ctx.globalAlpha = rand(.25, .9)
          ctx.fillRect(x, y, 5, 3)
        }
      }
    }
    ctx.globalAlpha = 1
  })
}

function stoneTexture() {
  return canvasTexture(1024, 1024, (ctx, w, h) => {
    const cx = w / 2, cy = h / 2
    const bg = ctx.createRadialGradient(cx, cy, 40, cx, cy, w * .54)
    bg.addColorStop(0, '#252330')
    bg.addColorStop(.44, '#171620')
    bg.addColorStop(.72, '#111018')
    bg.addColorStop(1, '#07070d')
    ctx.fillStyle = bg
    ctx.fillRect(0, 0, w, h)
    // Stone tiling.
    for (let i = 0; i < 90; i++) {
      const x = rand(0, w), y = rand(0, h), r = rand(25, 130)
      ctx.beginPath()
      ctx.arc(x, y, r, 0, Math.PI * 2)
      ctx.fillStyle = `rgba(${Math.random() < .5 ? '255,255,255' : '0,0,0'},${rand(.005, .025)})`
      ctx.fill()
    }
    // Concentric gold rings.
    for (const [radius, alpha, width] of [[398, .42, 3], [410, .13, 1], [345, .16, 1], [300, .52, 2], [210, .13, 1], [175, .34, 2]]) {
      ctx.beginPath()
      ctx.arc(cx, cy, radius, 0, Math.PI * 2)
      ctx.strokeStyle = `rgba(226,184,112,${alpha})`
      ctx.lineWidth = width
      ctx.stroke()
    }
    // Broken halo arcs.
    ctx.lineWidth = 7
    for (const [start, len] of [[.2, .9], [2.2, .55], [3.5, .75], [4.9, .32]]) {
      ctx.beginPath()
      ctx.arc(cx, cy, 455, start, start + len)
      ctx.strokeStyle = 'rgba(255,200,107,.13)'
      ctx.stroke()
    }
    // Center emblem — a sharp eight-point storm sigil.
    ctx.save()
    ctx.translate(cx, cy)
    ctx.strokeStyle = 'rgba(255,200,107,.55)'
    ctx.lineWidth = 4
    ctx.rotate(Math.PI / 8)
    for (let i = 0; i < 8; i++) {
      ctx.beginPath()
      ctx.moveTo(0, 38)
      ctx.lineTo(10, 132)
      ctx.lineTo(0, 112)
      ctx.lineTo(-10, 132)
      ctx.closePath()
      ctx.stroke()
      ctx.rotate(Math.PI / 4)
    }
    ctx.beginPath()
    ctx.arc(0, 0, 28, 0, Math.PI * 2)
    ctx.stroke()
    ctx.restore()
    // Radial cracks and scoring.
    for (let i = 0; i < 22; i++) {
      const a = rand(0, Math.PI * 2), r0 = rand(50, 300)
      ctx.beginPath()
      ctx.moveTo(cx + Math.cos(a) * r0, cy + Math.sin(a) * r0)
      for (let j = 1; j < 4; j++) {
        const rr = r0 + j * rand(20, 70)
        ctx.lineTo(cx + Math.cos(a + rand(-.04, .04)) * rr, cy + Math.sin(a + rand(-.04, .04)) * rr)
      }
      ctx.strokeStyle = 'rgba(0,0,0,.24)'
      ctx.lineWidth = rand(.5, 2)
      ctx.stroke()
    }
    // Wet glints.
    for (let i = 0; i < 60; i++) {
      const a = rand(0, Math.PI * 2), r = Math.sqrt(Math.random()) * 500
      const g = ctx.createRadialGradient(cx + Math.cos(a) * r, cy + Math.sin(a) * r, 0, cx + Math.cos(a) * r, cy + Math.sin(a) * r, rand(5, 30))
      g.addColorStop(0, `rgba(160,200,255,${rand(.02, .09)})`)
      g.addColorStop(1, 'rgba(160,200,255,0)')
      ctx.fillStyle = g
      ctx.fillRect(0, 0, w, h)
    }
  })
}

function neonSignTexture(glyph, color) {
  return canvasTexture(256, 512, (ctx, w, h) => {
    ctx.clearRect(0, 0, w, h)
    ctx.strokeStyle = color
    ctx.lineWidth = 7
    ctx.strokeRect(12, 12, w - 24, h - 24)
    ctx.shadowColor = color
    ctx.shadowBlur = 24
    ctx.fillStyle = color
    ctx.font = '230px "Bebas Neue", sans-serif'
    ctx.textAlign = 'center'
    ctx.textBaseline = 'middle'
    ctx.fillText(glyph, w / 2, h / 2)
    ctx.shadowBlur = 0
  })
}

export class Arena {
  constructor(scene, renderer) {
    this.scene = scene
    this.renderer = renderer
    this.time = 0
    this.flash = 0
    this.nextLightning = rand(8, 16)
    this.bolts = []
    this.embers = []
    this.buildLights()
    this.buildSky()
    this.buildCity()
    this.buildStage()
    this.buildTorii()
    this.buildProps()
    this.buildRain()
    this.buildLightning()
    this.buildMist()
  }

  buildLights() {
    const scene = this.scene
    scene.fog = new THREE.FogExp2(0x080a16, .018)
    const hemi = new THREE.HemisphereLight(0x5d7dff, 0x281a14, 1.1)
    scene.add(hemi)
    this.hemi = hemi
    const moon = new THREE.DirectionalLight(0x9ec4ff, 2.6)
    moon.position.set(-8, 13, -9)
    moon.castShadow = true
    moon.shadow.mapSize.set(1536, 1536)
    moon.shadow.camera.left = -10
    moon.shadow.camera.right = 10
    moon.shadow.camera.top = 12
    moon.shadow.camera.bottom = -3
    moon.shadow.camera.near = 1
    moon.shadow.camera.far = 40
    moon.shadow.bias = -.0008
    moon.shadow.normalBias = .02
    scene.add(moon)
    this.moonLight = moon
    const rim = new THREE.SpotLight(0xff4b2b, 70, 22, Math.PI * .22, .7, 1.6)
    rim.position.set(8, 7, -4)
    rim.target.position.set(0, 1.5, 0)
    scene.add(rim, rim.target)
    const fill = new THREE.SpotLight(0x33dcff, 55, 18, Math.PI * .28, .8, 1.8)
    fill.position.set(-7, 6, 5)
    fill.target.position.set(-1, 1.4, 0)
    scene.add(fill, fill.target)
    this.rim = rim
    this.fill = fill
    this.lanternLights = []
    for (const x of [-5.6, 5.6]) {
      const l = new THREE.PointLight(0xff7a32, 16, 8, 2)
      l.position.set(x, 3.3, -3.5)
      scene.add(l)
      this.lanternLights.push({ light: l, base: 16, seed: Math.random() * 10 })
    }
  }

  buildSky() {
    const geo = new THREE.SphereGeometry(90, 32, 20)
    const mat = new THREE.ShaderMaterial({
      side: THREE.BackSide,
      depthWrite: false,
      uniforms: {
        top: { value: new THREE.Color(0x02030a) },
        mid: { value: new THREE.Color(0x15132b) },
        horizon: { value: new THREE.Color(0x31213a) },
        moonDir: { value: new THREE.Vector3(-.45, .3, -.84).normalize() },
      },
      vertexShader: `varying vec3 vWorld; void main(){ vWorld=normalize(position); gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.); }`,
      fragmentShader: `
        varying vec3 vWorld; uniform vec3 top; uniform vec3 mid; uniform vec3 horizon; uniform vec3 moonDir;
        float hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
        float noise(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x),f.y);}
        void main(){
          float h=clamp(vWorld.y*.5+.5,0.,1.);
          vec3 col=mix(horizon,mid,smoothstep(.46,.67,h));
          col=mix(col,top,smoothstep(.64,.96,h));
          float moonDot=max(dot(vWorld,moonDir),0.);
          col+=vec3(.38,.46,.75)*pow(moonDot,90.)*.9;
          col+=vec3(.1,.12,.25)*pow(moonDot,12.)*.35;
          vec2 sp=vec2(atan(vWorld.z,vWorld.x),asin(clamp(vWorld.y,-1.,1.)))*vec2(38.,22.);
          float stars=step(.997,hash(floor(sp)))*smoothstep(.24,.72,h);
          col+=vec3(.7,.82,1.)*stars*.8;
          gl_FragColor=vec4(col,1.);
        }`
    })
    const sky = new THREE.Mesh(geo, mat)
    this.scene.add(sky)
    this.sky = sky

    const glowTex = radialGlowTexture()
    const glow = new THREE.Sprite(new THREE.SpriteMaterial({ map: glowTex, color: 0x8aa5ff, transparent: true, opacity: .3, blending: THREE.AdditiveBlending, depthWrite: false }))
    glow.scale.set(30, 30, 1)
    glow.position.set(-20, 15, -46)
    this.scene.add(glow)
    const moon = new THREE.Mesh(new THREE.CircleGeometry(4.2, 48), new THREE.MeshBasicMaterial({ color: 0xbcd1ff, fog: false, toneMapped: false }))
    moon.position.set(-20, 15, -45)
    moon.lookAt(0, 3, 4)
    this.scene.add(moon)
    const halo = new THREE.Sprite(new THREE.SpriteMaterial({ map: glowTex, color: 0x9ab8ff, transparent: true, opacity: .22, blending: THREE.AdditiveBlending, depthWrite: false }))
    halo.scale.set(17, 17, 1)
    halo.position.copy(moon.position)
    this.scene.add(halo)

    // Low storm clouds.
    this.clouds = []
    const cloudTex = canvasTexture(512, 256, (ctx, w, h) => {
      ctx.clearRect(0, 0, w, h)
      for (let i = 0; i < 70; i++) {
        const x = rand(0, w), y = rand(h * .25, h * .8), r = rand(18, 70)
        const g = ctx.createRadialGradient(x, y, 0, x, y, r)
        g.addColorStop(0, `rgba(22,25,48,${rand(.08, .2)})`)
        g.addColorStop(1, 'rgba(10,11,25,0)')
        ctx.fillStyle = g
        ctx.fillRect(x - r, y - r, r * 2, r * 2)
      }
    })
    for (let i = 0; i < 8; i++) {
      const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: cloudTex, transparent: true, opacity: rand(.5, .9), depthWrite: false }))
      s.scale.set(rand(30, 65), rand(12, 24), 1)
      s.position.set(rand(-55, 55), rand(14, 28), rand(-55, -20))
      this.scene.add(s)
      this.clouds.push({ sprite: s, speed: rand(.08, .22), baseY: s.position.y })
    }
  }

  buildCity() {
    this.city = new THREE.Group()
    this.scene.add(this.city)
    const windows = windowTexture()
    windows.wrapS = windows.wrapT = THREE.RepeatWrapping
    windows.repeat.set(2, 2)
    const buildingMat = new THREE.MeshStandardMaterial({
      color: 0x141827, map: windows, emissive: 0xffffff, emissiveMap: windows,
      emissiveIntensity: .58, roughness: .82, metalness: .22,
    })
    const darkMat = new THREE.MeshStandardMaterial({ color: 0x070912, roughness: .9, metalness: .1 })
    const placements = []
    for (let i = 0; i < 30; i++) {
      const angle = rand(-Math.PI * .98, Math.PI * .98)
      const radius = rand(20, 48)
      const x = Math.sin(angle) * radius
      const z = -Math.cos(angle) * radius - 8
      if (Math.abs(x) < 8 && z > -18) continue
      placements.push({ x, z, w: rand(3.2, 8), h: rand(8, 30), d: rand(3, 7) })
    }
    for (const p of placements) {
      const mesh = new THREE.Mesh(new THREE.BoxGeometry(p.w, p.h, p.d), Math.random() < .8 ? buildingMat : darkMat)
      mesh.position.set(p.x, p.h / 2 - 1.5, p.z)
      mesh.castShadow = false
      this.city.add(mesh)
      if (Math.random() < .28) {
        const color = Math.random() < .5 ? 0xff4d2e : 0x58f4ff
        const strip = new THREE.Mesh(new THREE.BoxGeometry(.1, p.h * .66, .1), new THREE.MeshBasicMaterial({ color, toneMapped: false }))
        strip.position.set(p.x + p.w * .5 + .08, p.h * .52 - 1, p.z + p.d * .5 + .08)
        this.city.add(strip)
      }
      if (Math.random() < .3) {
        const signTex = neonSignTexture(Math.random() < .5 ? '雷' : '風', Math.random() < .5 ? '#ff513b' : '#67f6ff')
        const sign = new THREE.Mesh(new THREE.PlaneGeometry(2.5, 5), new THREE.MeshBasicMaterial({ map: signTex, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false }))
        sign.position.set(p.x + p.w * .5 + .2, p.h * .62, p.z + p.d * .5 + .1)
        this.city.add(sign)
      }
    }
    // Distant bridge lights.
    const dotGeo = new THREE.BufferGeometry()
    const dots = []
    for (let i = 0; i < 160; i++) dots.push(rand(-50, 50), rand(1, 4), rand(-55, -30))
    dotGeo.setAttribute('position', new THREE.Float32BufferAttribute(dots, 3))
    const dotMat = new THREE.PointsMaterial({ color: 0xffa65c, size: .18, transparent: true, opacity: .6, blending: THREE.AdditiveBlending, depthWrite: false })
    this.city.add(new THREE.Points(dotGeo, dotMat))
  }

  buildStage() {
    const stage = new THREE.Group()
    this.scene.add(stage)
    const tex = stoneTexture()
    tex.anisotropy = Math.min(8, this.renderer.capabilities.getMaxAnisotropy())
    const topMat = new THREE.MeshPhysicalMaterial({
      map: tex, color: 0xffffff, roughness: .29, metalness: .26,
      clearcoat: .7, clearcoatRoughness: .25, envMapIntensity: .75,
    })
    const disk = new THREE.Mesh(new THREE.CircleGeometry(8.2, 96), topMat)
    disk.rotation.x = -Math.PI / 2
    disk.position.y = .01
    disk.receiveShadow = true
    stage.add(disk)
    const sideMat = new THREE.MeshStandardMaterial({ color: 0x090a11, roughness: .52, metalness: .45 })
    const base = new THREE.Mesh(new THREE.CylinderGeometry(8.22, 7.9, .72, 96), sideMat)
    base.position.y = -.36
    base.receiveShadow = true
    base.castShadow = true
    stage.add(base)
    // Golden lip.
    const lip = new THREE.Mesh(new THREE.TorusGeometry(8.2, .05, 6, 128), new THREE.MeshStandardMaterial({ color: 0xffc86b, emissive: 0xff9d2e, emissiveIntensity: 1.4, roughness: .3, metalness: .8, toneMapped: false }))
    lip.rotation.x = Math.PI / 2
    lip.position.y = .04
    stage.add(lip)
    // Under-glow ring.
    const under = new THREE.Mesh(new THREE.TorusGeometry(8.14, .12, 4, 128), new THREE.MeshBasicMaterial({ color: 0x28d8ff, toneMapped: false, transparent: true, opacity: .35 }))
    under.rotation.x = Math.PI / 2
    under.position.y = -.48
    stage.add(under)
    this.underRing = under
    // Outer ocean / sky deck.
    const waterMat = new THREE.MeshPhysicalMaterial({
      color: 0x03060e, roughness: .08, metalness: .72, clearcoat: 1, clearcoatRoughness: .06,
      envMapIntensity: 1.1,
    })
    const water = new THREE.Mesh(new THREE.CircleGeometry(58, 64), waterMat)
    water.rotation.x = -Math.PI / 2
    water.position.y = -.74
    water.receiveShadow = true
    stage.add(water)
    // Puddles on the stage.
    for (let i = 0; i < 6; i++) {
      const puddle = new THREE.Mesh(new THREE.CircleGeometry(rand(.5, 1.6), 28), new THREE.MeshPhysicalMaterial({ color: 0x0a1220, roughness: .04, metalness: .55, transparent: true, opacity: .63, clearcoat: 1 }))
      puddle.rotation.x = -Math.PI / 2
      puddle.position.set(rand(-5.5, 5.5), .025, rand(-3.4, 3.4))
      puddle.scale.y = rand(.45, 1)
      puddle.receiveShadow = true
      stage.add(puddle)
    }
    // Floating dust/gold motes on the platform.
    const moteGeo = new THREE.BufferGeometry()
    const arr = []
    for (let i = 0; i < 120; i++) arr.push(rand(-7.5, 7.5), rand(.2, 4.5), rand(-5.5, 5.5))
    moteGeo.setAttribute('position', new THREE.Float32BufferAttribute(arr, 3))
    const moteMat = new THREE.PointsMaterial({ color: 0xffc86b, size: .035, transparent: true, opacity: .42, blending: THREE.AdditiveBlending, depthWrite: false })
    this.motes = new THREE.Points(moteGeo, moteMat)
    stage.add(this.motes)
  }

  buildTorii() {
    const g = new THREE.Group()
    g.position.set(0, 0, -6.8)
    this.scene.add(g)
    const red = new THREE.MeshStandardMaterial({ color: 0x8b1b22, roughness: .46, metalness: .25 })
    const dark = new THREE.MeshStandardMaterial({ color: 0x11101a, roughness: .4, metalness: .55 })
    const gold = new THREE.MeshStandardMaterial({ color: 0xffbd68, emissive: 0xff8c2c, emissiveIntensity: .9, roughness: .28, metalness: .8 })
    for (const x of [-3.1, 3.1]) {
      const pillar = new THREE.Mesh(new THREE.CylinderGeometry(.23, .3, 5.3, 12), red)
      pillar.position.set(x, 2.55, 0)
      pillar.castShadow = true
      g.add(pillar)
      const base = new THREE.Mesh(new THREE.CylinderGeometry(.42, .5, .3, 12), dark)
      base.position.set(x, .15, 0)
      g.add(base)
      const lamp = new THREE.Mesh(new THREE.BoxGeometry(.34, .75, .34), new THREE.MeshStandardMaterial({ color: 0xffc86b, emissive: 0xff7a2e, emissiveIntensity: 2.4, roughness: .5, transparent: true, opacity: .9, toneMapped: false }))
      lamp.position.set(x, 4.35, 0)
      g.add(lamp)
    }
    const lower = new THREE.Mesh(new THREE.BoxGeometry(8.4, .28, .45), red)
    lower.position.y = 4.28
    lower.castShadow = true
    g.add(lower)
    const top = new THREE.Mesh(new THREE.BoxGeometry(10, .34, .55), red)
    top.position.y = 5.45
    top.rotation.z = .015
    top.castShadow = true
    g.add(top)
    const cap = new THREE.Mesh(new THREE.BoxGeometry(10.8, .2, .68), dark)
    cap.position.y = 5.66
    cap.rotation.z = .015
    g.add(cap)
    const trim = new THREE.Mesh(new THREE.BoxGeometry(9.5, .035, .03), gold)
    trim.position.set(0, 5.27, .3)
    g.add(trim)
    // Hanging banners.
    for (const x of [-2.25, 2.25]) {
      const banner = new THREE.Mesh(new THREE.PlaneGeometry(.72, 1.6), new THREE.MeshStandardMaterial({ color: 0xd9d0bd, roughness: .9, side: THREE.DoubleSide }))
      banner.position.set(x, 3.35, .08)
      g.add(banner)
      const glyphTex = neonSignTexture(x < 0 ? '風' : '雷', '#181018')
      const glyph = new THREE.Mesh(new THREE.PlaneGeometry(.6, .6), new THREE.MeshBasicMaterial({ map: glyphTex, transparent: true }))
      glyph.position.set(x, 3.5, .09)
      g.add(glyph)
    }
    this.torii = g
  }

  buildProps() {
    const group = new THREE.Group()
    this.scene.add(group)
    const stone = new THREE.MeshStandardMaterial({ color: 0x171820, roughness: .7, metalness: .15 })
    const red = new THREE.MeshStandardMaterial({ color: 0x762026, roughness: .55 })
    const gold = new THREE.MeshStandardMaterial({ color: 0xffc16b, emissive: 0xff862e, emissiveIntensity: 1.1, roughness: .4 })
    // Lantern posts.
    for (const x of [-5.6, 5.6]) {
      const post = new THREE.Mesh(new THREE.CylinderGeometry(.07, .11, 2.4, 8), stone)
      post.position.set(x, 1.2, -3.5)
      group.add(post)
      const arm = new THREE.Mesh(new THREE.BoxGeometry(.86, .07, .07), stone)
      arm.position.set(x + (x > 0 ? -.25 : .25), 2.36, -3.5)
      group.add(arm)
      const lantern = new THREE.Mesh(new THREE.CylinderGeometry(.24, .19, .62, 8), gold)
      lantern.position.set(x + (x > 0 ? -.48 : .48), 2.05, -3.5)
      group.add(lantern)
      const cap = new THREE.Mesh(new THREE.ConeGeometry(.32, .2, 8), stone)
      cap.position.set(lantern.position.x, 2.44, -3.5)
      group.add(cap)
    }
    // Bamboo clusters at the edges.
    const bambooMat = new THREE.MeshStandardMaterial({ color: 0x1f3a2c, roughness: .7 })
    for (let i = 0; i < 12; i++) {
      const side = i % 2 ? 1 : -1
      const h = rand(2.4, 4.2)
      const b = new THREE.Mesh(new THREE.CylinderGeometry(.035, .05, h, 5), bambooMat)
      b.position.set(side * rand(6.5, 8.2), h / 2, rand(-5.5, -2.2))
      b.rotation.z = rand(-.08, .08)
      group.add(b)
    }
    // Training posts / carved stones.
    for (const [x, z, s] of [[-6.2, 1.5, .7], [6.4, .8, .9], [-6.5, -1.1, .4]]) {
      const rock = new THREE.Mesh(new THREE.DodecahedronGeometry(s, 0), stone)
      rock.position.set(x, s * .45, z)
      rock.rotation.set(rand(0, 1), rand(0, 3), rand(0, 1))
      rock.scale.y = rand(.6, 1.1)
      group.add(rock)
    }
    // Floating banners left/right.
    for (const x of [-7.5, 7.5]) {
      const pole = new THREE.Mesh(new THREE.CylinderGeometry(.05, .06, 5.8, 6), stone)
      pole.position.set(x, 2.9, -1.5)
      group.add(pole)
      const flagTex = canvasTexture(256, 512, (ctx, w, h) => {
        ctx.fillStyle = x < 0 ? '#103849' : '#421016'
        ctx.fillRect(0, 0, w, h)
        ctx.strokeStyle = x < 0 ? '#54eaff' : '#ff513b'
        ctx.lineWidth = 4
        ctx.strokeRect(12, 12, w - 24, h - 24)
        ctx.fillStyle = x < 0 ? '#9ffaff' : '#ffb0a0'
        ctx.font = '180px "Bebas Neue", sans-serif'
        ctx.textAlign = 'center'
        ctx.fillText(x < 0 ? '風' : '雷', w / 2, h / 2)
      })
      const flag = new THREE.Mesh(new THREE.PlaneGeometry(1.1, 2.5), new THREE.MeshStandardMaterial({ map: flagTex, side: THREE.DoubleSide, roughness: .95 }))
      flag.position.set(x + (x < 0 ? .58 : -.58), 4.3, -1.5)
      flag.userData.phase = rand(0, 5)
      group.add(flag)
      this.flags = this.flags || []
      this.flags.push(flag)
    }
  }

  buildRain() {
    const count = 1400
    const positions = new Float32Array(count * 6)
    this.rainDrops = []
    for (let i = 0; i < count; i++) {
      const x = rand(-18, 18), y = rand(0, 19), z = rand(-12, 15)
      const len = rand(.18, .55)
      positions[i * 6] = x
      positions[i * 6 + 1] = y
      positions[i * 6 + 2] = z
      positions[i * 6 + 3] = x - .035
      positions[i * 6 + 4] = y - len
      positions[i * 6 + 5] = z
      this.rainDrops.push({ x, y, z, len, speed: rand(13, 23) })
    }
    const geo = new THREE.BufferGeometry()
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3))
    const mat = new THREE.LineBasicMaterial({ color: 0x8db4ff, transparent: true, opacity: .3, blending: THREE.AdditiveBlending, depthWrite: false })
    this.rain = new THREE.LineSegments(geo, mat)
    this.rain.frustumCulled = false
    this.scene.add(this.rain)
    this.rainPositions = positions
  }

  buildLightning() {
    this.boltGroup = new THREE.Group()
    this.scene.add(this.boltGroup)
  }

  buildMist() {
    const tex = radialGlowTexture()
    this.mist = []
    for (let i = 0; i < 5; i++) {
      const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, color: 0x4466bb, transparent: true, opacity: rand(.035, .08), depthWrite: false }))
      s.scale.set(rand(14, 30), rand(3, 7), 1)
      s.position.set(rand(-12, 12), rand(.5, 2), rand(-3, 3))
      this.scene.add(s)
      this.mist.push(s)
    }
  }

  strikeLightning(intensity = 1) {
    if (!this.scene) return
    const materials = []
    const startX = rand(-14, 14)
    for (let b = 0; b < 3; b++) {
      const points = []
      let x = startX + rand(-3, 3), y = 21, z = rand(-24, -10)
      const targetX = rand(-5, 5), targetZ = rand(-9, -2)
      for (let i = 0; i < 13; i++) {
        points.push(new THREE.Vector3(x, y, z))
        x += (targetX - x) * .18 + rand(-1.2, 1.2)
        y -= 1.55
        z += (targetZ - z) * .14 + rand(-.5, .5)
      }
      const geo = new THREE.BufferGeometry().setFromPoints(points)
      const mat = new THREE.LineBasicMaterial({ color: b === 0 ? 0xe7f2ff : 0x89b5ff, transparent: true, opacity: .95, blending: THREE.AdditiveBlending, depthWrite: false })
      const line = new THREE.Line(geo, mat)
      this.boltGroup.add(line)
      materials.push({ mat, life: .28 + b * .05 })
    }
    this.bolts.push({ materials, life: .35 })
    this.flash = Math.max(this.flash, .9 * intensity)
    if (this.onFlash) this.onFlash(intensity)
  }

  update(dt, time, camera) {
    this.time = time
    // Rain.
    const arr = this.rainPositions
    const drops = this.rainDrops
    for (let i = 0; i < drops.length; i++) {
      const d = drops[i]
      d.y -= d.speed * dt
      if (d.y < -.5) { d.y = rand(17, 21); d.x = rand(-18, 18); d.z = rand(-12, 15) }
      arr[i * 6] = d.x
      arr[i * 6 + 1] = d.y
      arr[i * 6 + 2] = d.z
      arr[i * 6 + 3] = d.x - .04
      arr[i * 6 + 4] = d.y - d.len
      arr[i * 6 + 5] = d.z
    }
    this.rain.geometry.attributes.position.needsUpdate = true

    // Clouds.
    for (const c of this.clouds) {
      c.sprite.position.x += c.speed * dt
      if (c.sprite.position.x > 58) c.sprite.position.x = -58
      c.sprite.position.y = c.baseY + Math.sin(time * .1 + c.speed * 10) * .5
    }
    // Neon flicker.
    this.rim.intensity = 70 + Math.sin(time * 1.3) * 5
    this.fill.intensity = 55 + Math.sin(time * .9 + 1) * 4
    for (const l of this.lanternLights) {
      l.light.intensity = l.base * (0.82 + Math.sin(time * 8 + l.seed) * .05 + Math.random() * .07)
    }
    this.underRing.material.opacity = .28 + Math.sin(time * 2.2) * .1
    // Mist drift.
    for (let i = 0; i < this.mist.length; i++) {
      const m = this.mist[i]
      m.position.x += (i % 2 ? 1 : -1) * dt * .23
      if (m.position.x > 15) m.position.x = -15
      if (m.position.x < -15) m.position.x = 15
    }
    // Flags.
    if (this.flags) {
      for (const f of this.flags) {
        f.rotation.y = Math.sin(time * 1.4 + f.userData.phase) * .15
        f.rotation.z = Math.sin(time * 1.8 + f.userData.phase) * .025
      }
    }
    // Embers / motes.
    const mp = this.motes.geometry.attributes.position
    for (let i = 0; i < mp.count; i++) {
      let y = mp.getY(i) + dt * .11
      if (y > 4.5) y = .2
      mp.setY(i, y)
    }
    mp.needsUpdate = true

    // Lightning lifecycle.
    for (let i = this.bolts.length - 1; i >= 0; i--) {
      const b = this.bolts[i]
      b.life -= dt
      for (const m of b.materials) m.mat.opacity = clamp(b.life * 2.4, 0, 1) * .9
      if (b.life <= 0) {
        this.boltGroup.clear()
        this.bolts.splice(i, 1)
      }
    }
    this.flash = Math.max(0, this.flash - dt * 3.8)
    this.moonLight.intensity = 2.6 + this.flash * 4
    this.hemi.intensity = 1.1 + this.flash * 1.6
    // Ambient occasional storm strike.
    this.nextLightning -= dt
    if (this.nextLightning <= 0) {
      this.strikeLightning(.7)
      this.nextLightning = rand(9, 19)
      if (this.onThunder) this.onThunder()
    }
  }
}

import * as THREE from 'three'

const clamp = (v, a, b) => Math.max(a, Math.min(b, v))

function glowTexture() {
  const c = document.createElement('canvas')
  c.width = c.height = 128
  const ctx = c.getContext('2d')
  const g = ctx.createRadialGradient(64, 64, 0, 64, 64, 64)
  g.addColorStop(0, 'rgba(255,255,255,1)')
  g.addColorStop(.18, 'rgba(255,255,255,.85)')
  g.addColorStop(.5, 'rgba(255,255,255,.22)')
  g.addColorStop(1, 'rgba(255,255,255,0)')
  ctx.fillStyle = g
  ctx.fillRect(0, 0, 128, 128)
  return new THREE.CanvasTexture(c)
}

class ParticleField {
  constructor(scene, max = 700) {
    this.max = max
    this.cursor = 0
    this.positions = new Float32Array(max * 3)
    this.colors = new Float32Array(max * 3)
    this.sizes = new Float32Array(max)
    this.alphas = new Float32Array(max)
    this.vel = new Float32Array(max * 3)
    this.life = new Float32Array(max)
    this.maxLife = new Float32Array(max)
    this.gravity = new Float32Array(max)
    this.drag = new Float32Array(max)
    const geo = new THREE.BufferGeometry()
    geo.setAttribute('position', new THREE.BufferAttribute(this.positions, 3))
    geo.setAttribute('color', new THREE.BufferAttribute(this.colors, 3))
    geo.setAttribute('aSize', new THREE.BufferAttribute(this.sizes, 1))
    geo.setAttribute('aAlpha', new THREE.BufferAttribute(this.alphas, 1))
    const mat = new THREE.ShaderMaterial({
      uniforms: { uPixel: { value: Math.min(2, window.devicePixelRatio || 1) } },
      vertexShader: `
        attribute float aSize; attribute float aAlpha; attribute vec3 color;
        varying vec3 vColor; varying float vAlpha;
        uniform float uPixel;
        void main(){
          vColor=color; vAlpha=aAlpha;
          vec4 mv=modelViewMatrix*vec4(position,1.);
          gl_PointSize=aSize*uPixel*220./max(1.,-mv.z);
          gl_Position=projectionMatrix*mv;
        }`,
      fragmentShader: `
        varying vec3 vColor; varying float vAlpha;
        void main(){
          vec2 p=gl_PointCoord-.5; float d=length(p);
          float a=smoothstep(.5,.05,d)*vAlpha;
          gl_FragColor=vec4(vColor,a);
        }`,
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
    })
    this.points = new THREE.Points(geo, mat)
    this.points.frustumCulled = false
    scene.add(this.points)
    this.scene = scene
  }

  spawn(pos, color, { count = 10, speed = 5, size = .12, life = .5, gravity = -6, drag = 2.4, spread = 1, direction = null, ember = false } = {}) {
    for (let i = 0; i < count; i++) {
      const idx = this.cursor
      this.cursor = (this.cursor + 1) % this.max
      let vx, vy, vz
      if (direction) {
        vx = direction.x + (Math.random() - .5) * spread
        vy = direction.y + (Math.random() - .5) * spread
        vz = direction.z + (Math.random() - .5) * spread
      } else {
        const theta = Math.random() * Math.PI * 2
        const phi = Math.acos(2 * Math.random() - 1)
        const s = speed * (0.25 + Math.random() * .85)
        vx = Math.sin(phi) * Math.cos(theta) * s
        vy = Math.cos(phi) * s
        vz = Math.sin(phi) * Math.sin(theta) * s
      }
      this.positions[idx * 3] = pos.x + (Math.random() - .5) * .08
      this.positions[idx * 3 + 1] = pos.y + (Math.random() - .5) * .08
      this.positions[idx * 3 + 2] = pos.z + (Math.random() - .5) * .08
      this.vel[idx * 3] = vx
      this.vel[idx * 3 + 1] = vy
      this.vel[idx * 3 + 2] = vz
      const c = color.clone()
      if (ember) c.offsetHSL(0, 0, (Math.random() - .5) * .05)
      this.colors[idx * 3] = c.r
      this.colors[idx * 3 + 1] = c.g
      this.colors[idx * 3 + 2] = c.b
      this.sizes[idx] = size * (0.45 + Math.random() * 1.1)
      this.alphas[idx] = 1
      const l = life * (0.55 + Math.random() * .8)
      this.life[idx] = l
      this.maxLife[idx] = l
      this.gravity[idx] = gravity
      this.drag[idx] = drag
    }
  }

  update(dt) {
    const p = this.positions, v = this.vel
    for (let i = 0; i < this.max; i++) {
      if (this.life[i] <= 0) { this.alphas[i] = 0; continue }
      this.life[i] -= dt
      const l = Math.max(0, this.life[i])
      const d = Math.exp(-this.drag[i] * dt)
      v[i * 3] *= d
      v[i * 3 + 1] = v[i * 3 + 1] * d + this.gravity[i] * dt
      v[i * 3 + 2] *= d
      p[i * 3] += v[i * 3] * dt
      p[i * 3 + 1] += v[i * 3 + 1] * dt
      p[i * 3 + 2] += v[i * 3 + 2] * dt
      const t = l / this.maxLife[i]
      this.alphas[i] = Math.min(1, t * 2.2)
    }
    const g = this.points.geometry
    g.attributes.position.needsUpdate = true
    g.attributes.color.needsUpdate = true
    g.attributes.aSize.needsUpdate = true
    g.attributes.aAlpha.needsUpdate = true
  }
}

export class FX {
  constructor(scene, camera) {
    this.scene = scene
    this.camera = camera
    this.particles = new ParticleField(scene)
    this.rings = []
    this.shockwaves = []
    this.slashes = []
    this.glowTex = glowTexture()
    this.projectiles = []
    this.bolts = []
  }

  burst(pos, color, opts = {}) {
    this.particles.spawn(pos, new THREE.Color(color), opts)
  }

  impact(pos, color = 0xffd27a, scale = 1, blocked = false) {
    const c = new THREE.Color(color)
    this.particles.spawn(pos, c, { count: blocked ? 12 : 26, speed: blocked ? 3 : 7, size: .13 * scale, life: .45, gravity: -8 })
    this.particles.spawn(pos, new THREE.Color(0xffffff), { count: 10, speed: 4.5, size: .08 * scale, life: .28, gravity: -3 })
    // Flash ring.
    const ring = new THREE.Mesh(
      new THREE.RingGeometry(.17, .25, 28),
      new THREE.MeshBasicMaterial({ color: blocked ? 0x7febff : c, transparent: true, opacity: .95, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide, toneMapped: false })
    )
    ring.position.copy(pos)
    ring.position.z += .2
    ring.scale.setScalar(scale)
    ring.userData.life = .28
    ring.userData.maxLife = .28
    ring.userData.grow = 6 * scale
    this.scene.add(ring)
    this.rings.push(ring)
    // Star flare.
    const flare = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.glowTex, color: blocked ? 0x9ffaff : 0xffe0a0, transparent: true, opacity: 1, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false }))
    flare.position.copy(pos)
    flare.scale.setScalar(2.1 * scale)
    flare.userData.life = .17
    flare.userData.maxLife = .17
    flare.userData.flare = true
    this.scene.add(flare)
    this.rings.push(flare)
  }

  slash(pos, color, rotation = 0) {
    const geo = new THREE.RingGeometry(.55, .74, 28, 1, 0, Math.PI * 1.08)
    const mesh = new THREE.Mesh(geo, new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 1, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide, toneMapped: false }))
    mesh.position.copy(pos)
    mesh.position.z += .4
    mesh.rotation.z = rotation
    mesh.userData.life = .3
    mesh.userData.maxLife = .3
    mesh.userData.grow = 3.5
    this.scene.add(mesh)
    this.slashes.push(mesh)
  }

  groundWave(x, z, color = 0xffb35e, scale = 1) {
    const ring = new THREE.Mesh(
      new THREE.RingGeometry(.7, .82, 48),
      new THREE.MeshBasicMaterial({ color, transparent: true, opacity: .9, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide, toneMapped: false })
    )
    ring.rotation.x = -Math.PI / 2
    ring.position.set(x, .045, z)
    ring.userData.life = .55
    ring.userData.maxLife = .55
    ring.userData.grow = 9 * scale
    this.scene.add(ring)
    this.shockwaves.push(ring)
    this.burst(new THREE.Vector3(x, .3, z), color, { count: 24, speed: 10, size: .14, life: .8, gravity: 3, drag: 2.2 })
  }

  dust(x, z, color = 0x8899aa) {
    this.particles.spawn(new THREE.Vector3(x, .16, z), new THREE.Color(color), { count: 5, speed: 1.8, size: .09, life: .5, gravity: 3, drag: 3 })
  }

  lightningStrike(x, z, color = 0xdbeaff) {
    const group = new THREE.Group()
    for (let i = 0; i < 3; i++) {
      const pts = []
      let px = x + (Math.random() - .5) * 3, py = 18, pz = z + (Math.random() - .5) * 2
      for (let j = 0; j < 12; j++) {
        pts.push(new THREE.Vector3(px, py, pz))
        px += (x - px) * .2 + (Math.random() - .5) * 1.1
        py -= 1.45
        pz += (z - pz) * .2 + (Math.random() - .5) * .8
      }
      const line = new THREE.Line(
        new THREE.BufferGeometry().setFromPoints(pts),
        new THREE.LineBasicMaterial({ color: i ? 0x7db6ff : color, transparent: true, opacity: 1, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false })
      )
      group.add(line)
    }
    this.scene.add(group)
    this.bolts.push({ group, life: .24 })
    this.groundWave(x, z, color, 1.7)
    this.burst(new THREE.Vector3(x, 1.6, z), 0xffffff, { count: 45, speed: 12, size: .18, life: .7, gravity: -3, drag: 1.8 })
  }

  spawnProjectile(owner, fx = 1) {
    const color = owner.config.glow
    const g = new THREE.Group()
    const dir = owner.forward
    const core = new THREE.Mesh(new THREE.IcosahedronGeometry(.19, 2), new THREE.MeshBasicMaterial({ color: 0xffffff, toneMapped: false }))
    g.add(core)
    const shell = new THREE.Mesh(
      new THREE.IcosahedronGeometry(.33, 2),
      new THREE.MeshBasicMaterial({ color, transparent: true, opacity: .55, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false })
    )
    g.add(shell)
    const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.glowTex, color, transparent: true, opacity: .8, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false }))
    sprite.scale.setScalar(2.2)
    g.add(sprite)
    for (let i = 0; i < 2; i++) {
      const ring = new THREE.Mesh(
        new THREE.TorusGeometry(.42 + i * .1, .018, 4, 26),
        new THREE.MeshBasicMaterial({ color, transparent: true, opacity: .8, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false })
      )
      ring.rotation.x = Math.random() * Math.PI
      ring.rotation.y = Math.random() * Math.PI
      g.add(ring)
      g.userData[`ring${i}`] = ring
    }
    const light = new THREE.PointLight(color, 22, 4, 2)
    g.add(light)
    g.position.set(owner.x + dir * .6, 1.05, .1)
    this.scene.add(g)
    const p = { group: g, owner, dir, speed: 9.2 * fx, life: 2.2, hit: false, radius: .4, trail: 0 }
    this.projectiles.push(p)
    return p
  }

  update(dt, time) {
    this.particles.update(dt)
    for (let i = this.rings.length - 1; i >= 0; i--) {
      const r = this.rings[i]
      r.userData.life -= dt
      const t = Math.max(0, r.userData.life / r.userData.maxLife)
      if (r.userData.flare) {
        r.material.opacity = t
        r.scale.setScalar(2.1 + (1 - t) * 1.4)
      } else {
        r.material.opacity = t * .9
        const s = 1 + (1 - t) * r.userData.grow
        r.scale.set(s, s, s)
      }
      if (r.userData.life <= 0) { this.scene.remove(r); r.geometry?.dispose(); r.material.dispose(); this.rings.splice(i, 1) }
    }
    for (let i = this.slashes.length - 1; i >= 0; i--) {
      const r = this.slashes[i]
      r.userData.life -= dt
      const t = Math.max(0, r.userData.life / r.userData.maxLife)
      r.material.opacity = t
      r.rotation.z += dt * 5
      const s = 1 + (1 - t) * r.userData.grow
      r.scale.set(s, s, s)
      if (r.userData.life <= 0) { this.scene.remove(r); r.geometry.dispose(); r.material.dispose(); this.slashes.splice(i, 1) }
    }
    for (let i = this.shockwaves.length - 1; i >= 0; i--) {
      const r = this.shockwaves[i]
      r.userData.life -= dt
      const t = Math.max(0, r.userData.life / r.userData.maxLife)
      r.material.opacity = t * .9
      const s = 1 + (1 - t) * r.userData.grow
      r.scale.set(s, s, 1)
      if (r.userData.life <= 0) { this.scene.remove(r); r.geometry.dispose(); r.material.dispose(); this.shockwaves.splice(i, 1) }
    }
    for (let i = this.bolts.length - 1; i >= 0; i--) {
      const b = this.bolts[i]
      b.life -= dt
      b.group.children.forEach((l, j) => { l.material.opacity = clamp(b.life * (j ? 4 : 6), 0, 1) })
      if (b.life <= 0) {
        this.scene.remove(b.group)
        b.group.traverse(o => { o.geometry?.dispose(); o.material?.dispose() })
        this.bolts.splice(i, 1)
      }
    }
    // Projectiles.
    for (let i = this.projectiles.length - 1; i >= 0; i--) {
      const p = this.projectiles[i]
      if (p.hit) continue
      p.life -= dt
      p.group.position.x += p.dir * p.speed * dt
      p.group.position.y = 1.05 + Math.sin(time * 12 + p.group.position.x) * .05
      p.group.children.forEach(o => {
        if (o.isMesh && o.geometry?.type === 'TorusGeometry') {
          o.rotation.x += dt * 7
          o.rotation.y += dt * 5
        }
        if (o.isMesh && o.geometry?.type === 'IcosahedronGeometry') {
          o.rotation.y += dt * 6
        }
      })
      p.trail -= dt
      if (p.trail <= 0) {
        p.trail = .028
        this.particles.spawn(p.group.position.clone(), new THREE.Color(p.owner.config.glow), { count: 2, speed: 1.2, size: .14, life: .35, gravity: 1.5, drag: 4 })
      }
      if (p.life <= 0 || Math.abs(p.group.position.x) > 9) {
        this.despawnProjectile(p)
        this.projectiles.splice(i, 1)
      }
    }
  }

  despawnProjectile(p) {
    if (!p || p.hit) return
    p.hit = true
    this.burst(p.group.position.clone(), p.owner?.config?.glow ?? 0xffaa55, { count: 18, speed: 4, size: .14, life: .5 })
    this.scene.remove(p.group)
    p.group.traverse(o => { o.geometry?.dispose(); o.material?.dispose() })
  }

  clearProjectiles() {
    for (const p of this.projectiles) {
      if (!p.hit) {
        this.scene.remove(p.group)
        p.group.traverse(o => { o.geometry?.dispose(); o.material?.dispose() })
      }
    }
    this.projectiles.length = 0
  }
}

const $ = (id) => document.getElementById(id)

const SPECIAL_COSTS = { palm: 25, rush: 40, storm: 60 }

export class UI {
  constructor() {
    this.el = {
      hud: $('hud'), menu: $('menu'), pause: $('pauseOverlay'), result: $('resultOverlay'),
      playerHealth: $('playerHealth'), playerLag: $('playerLag'),
      enemyHealth: $('enemyHealth'), enemyLag: $('enemyLag'),
      playerMeter: $('playerMeter'), enemyMeter: $('enemyMeter'),
      playerMeterValue: $('playerMeterValue'), enemyMeterValue: $('enemyMeterValue'),
      playerPips: $('playerPips'), enemyPips: $('enemyPips'),
      timer: $('timer'), roundLabel: $('roundLabel'),
      guardFill: $('guardFill'), guardIndicator: $('guardIndicator'),
      announcer: $('announcer'), sub: $('subAnnouncer'), damageLayer: $('damageLayer'),
      combo: $('comboBadge'), comboCount: $('comboCount'),
      touch: $('touchControls'), pauseBtn: $('pauseBtn'), rotate: $('rotateHint'),
      resultTitle: $('resultTitle'), resultSubtitle: $('resultSubtitle'),
      resultEyebrow: $('resultEyebrow'), resultRounds: $('resultRounds'),
      resultCombo: $('resultCombo'), resultChi: $('resultChi'),
      impact: $('impactFlash'), lightning: $('lightningFlash'), boot: $('bootLoader'),
    }
    this.cards = [...document.querySelectorAll('.special-card')]
    this.health = { player: 100, enemy: 100 }
    this.lag = { player: 100, enemy: 100 }
    this.lagTimer = 0
    this.announceTimeout = 0
    this.comboTimeout = 0
    this.touchMode = matchMedia('(pointer: coarse)').matches || innerWidth < 760
    if (this.touchMode) this.el.touch.classList.remove('is-hidden')
    this.el.touch.classList.toggle('is-hidden', !this.touchMode)
  }

  hideBoot() {
    this.el.boot.classList.add('done')
    setTimeout(() => this.el.boot.remove(), 800)
  }

  showMenu() {
    this.el.menu.classList.remove('is-hidden')
    this.el.hud.classList.add('is-hidden')
    this.el.pause.classList.add('is-hidden')
    this.el.result.classList.add('is-hidden')
    this.el.pauseBtn.classList.add('is-hidden')
  }

  showGame() {
    this.el.menu.classList.add('is-hidden')
    this.el.hud.classList.remove('is-hidden')
    this.el.result.classList.add('is-hidden')
    this.el.pauseBtn.classList.remove('is-hidden')
    this.el.pause.classList.add('is-hidden')
    if (this.touchMode) this.el.touch.classList.remove('is-hidden')
  }

  showPause(paused) {
    this.el.pause.classList.toggle('is-hidden', !paused)
  }

  setHealth(side, value) {
    const v = Math.max(0, Math.min(100, value))
    this.health[side] = v
    const fill = side === 'player' ? this.el.playerHealth : this.el.enemyHealth
    fill.style.transform = `scaleX(${v / 100})`
    this.lagTimer = .4
    const shell = fill.closest('.health-shell')
    shell.classList.toggle('critical', v <= 25 && v > 0)
  }

  setLag(values) {
    for (const side of ['player', 'enemy']) {
      const target = Math.max(0, Math.min(100, values[side]))
      this.lag[side] += (target - this.lag[side]) * .04
      const el = side === 'player' ? this.el.playerLag : this.el.enemyLag
      el.style.transform = `scaleX(${this.lag[side] / 100})`
    }
  }

  setEnergy(side, value) {
    const v = Math.max(0, Math.min(100, value))
    const fill = side === 'player' ? this.el.playerMeter : this.el.enemyMeter
    fill.style.transform = `scaleX(${v / 100})`
    const label = side === 'player' ? this.el.playerMeterValue : this.el.enemyMeterValue
    label.textContent = Math.floor(v)
    if (side === 'player') {
      for (const card of this.cards) {
        const cost = SPECIAL_COSTS[card.dataset.move]
        card.classList.toggle('ready', v >= cost)
      }
    }
  }

  setGuard(value) {
    this.el.guardFill.style.width = `${Math.max(0, value)}%`
    this.el.guardIndicator.classList.toggle('danger', value < 35)
  }

  setTimer(value) {
    this.el.timer.textContent = String(Math.max(0, Math.ceil(value))).padStart(2, '0')
    this.el.timer.parentElement.classList.toggle('danger', value <= 10)
  }

  setRound(round) {
    this.el.roundLabel.textContent = `ROUND ${round}`
  }

  setWins(wins) {
    ;[...this.el.playerPips.children].forEach((p, i) => p.classList.toggle('won', i < wins[0]))
    ;[...this.el.enemyPips.children].forEach((p, i) => p.classList.toggle('won', i < wins[1]))
  }

  specialActive(name, ms = 260) {
    const card = this.cards.find(c => c.dataset.move === name)
    if (!card) return
    card.classList.add('active')
    setTimeout(() => card.classList.remove('active'), ms)
  }

  specialDenied(name) {
    const card = this.cards.find(c => c.dataset.move === name)
    if (!card) return
    card.classList.remove('denied')
    void card.offsetWidth
    card.classList.add('denied')
  }

  announce(text, sub = '', kind = '') {
    this.el.announcer.textContent = text
    this.el.announcer.className = `announcer ${kind ? `kind-${kind}` : ''}`
    this.el.sub.textContent = sub
    this.el.sub.className = 'sub-announcer'
    void this.el.announcer.offsetWidth
    this.el.announcer.classList.add('show')
    if (sub) this.el.sub.classList.add('show')
    clearTimeout(this.announceTimeout)
    this.announceTimeout = setTimeout(() => {
      this.el.announcer.classList.remove('show')
      this.el.sub.classList.remove('show')
    }, kind === 'ko' ? 2200 : 1150)
  }

  flash(kind = 'impact') {
    const el = kind === 'lightning' ? this.el.lightning : this.el.impact
    el.classList.remove('fire')
    void el.offsetWidth
    el.classList.add('fire')
  }

  combo(hits) {
    if (hits < 2) {
      this.el.combo.classList.remove('show')
      return
    }
    this.el.comboCount.textContent = hits
    this.el.combo.classList.add('show')
    clearTimeout(this.comboTimeout)
    this.comboTimeout = setTimeout(() => this.el.combo.classList.remove('show'), 1100)
  }

  hideCombo() {
    this.el.combo.classList.remove('show')
  }

  damageAt(world, camera, amount, crit = false) {
    const v = world.clone().project(camera)
    const x = (v.x * .5 + .5) * innerWidth
    const y = (-v.y * .5 + .5) * innerHeight
    const el = document.createElement('div')
    el.className = `damage-number${crit ? ' crit' : ''}`
    el.textContent = amount
    el.style.left = `${x}px`
    el.style.top = `${y}px`
    el.style.position = 'absolute'
    this.el.damageLayer.appendChild(el)
    setTimeout(() => el.remove(), 850)
  }

  showResult({ won, rounds, maxCombo, chi }) {
    this.el.result.classList.remove('is-hidden')
    this.el.pauseBtn.classList.add('is-hidden')
    this.el.resultTitle.textContent = won ? 'VICTORY' : 'DEFEAT'
    this.el.resultEyebrow.textContent = won ? 'MATCH COMPLETE · FLAWLESS STORM' : 'MATCH COMPLETE · THE STORM ENDURES'
    this.el.resultSubtitle.textContent = won ? 'The storm bows to the gale.' : 'The crown roof claims another challenger.'
    this.el.resultRounds.textContent = `${rounds[0]} — ${rounds[1]}`
    this.el.resultCombo.textContent = `${maxCombo} HITS`
    this.el.resultChi.textContent = chi
    this.el.result.querySelector('.result-panel').classList.toggle('defeat', !won)
  }

  hideResult() {
    this.el.result.classList.add('is-hidden')
  }

  setPaused(paused) {
    this.el.pause.classList.toggle('is-hidden', !paused)
  }
}

import * as THREE from 'three'
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js'
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js'
import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js'
import { OutputPass } from 'three/addons/postprocessing/OutputPass.js'
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js'
import { Arena } from './arena.js'
import { FX } from './fx.js'
import { Fighter, FIGHTERS } from './fighter.js'
import { UI } from './ui.js'
import { SoundEngine } from './audio.js'

const ui = new UI()
const sound = new SoundEngine()
const canvas = document.getElementById('stage')

const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: false,
  powerPreference: 'high-performance',
  alpha: false,
})
const isMobile = matchMedia('(pointer: coarse)').matches || innerWidth < 760
const maxDpr = isMobile ? 1.35 : 1.5
renderer.setPixelRatio(Math.min(devicePixelRatio || 1, maxDpr))
renderer.setSize(innerWidth, innerHeight, false)
renderer.outputColorSpace = THREE.SRGBColorSpace
renderer.toneMapping = THREE.ACESFilmicToneMapping
renderer.toneMappingExposure = 1.08
renderer.shadowMap.enabled = true
renderer.shadowMap.type = THREE.PCFSoftShadowMap

const scene = new THREE.Scene()
const camera = new THREE.PerspectiveCamera(44, innerWidth / innerHeight, .1, 160)
camera.position.set(0, 3.1, 10.8)

const pmrem = new THREE.PMREMGenerator(renderer)
const envTex = pmrem.fromScene(new RoomEnvironment(), .04).texture
scene.environment = envTex
scene.environmentIntensity = .28
pmrem.dispose()

const arena = new Arena(scene, renderer)
const fx = new FX(scene, camera)

const player = new Fighter(FIGHTERS.kaze, { x: -2.35, facing: 1, isPlayer: true })
const enemy = new Fighter(FIGHTERS.shogun, { x: 2.35, facing: -1 })
scene.add(player.root, enemy.root)

// Cinematic rim cards floating behind the fighters.
const cardGroup = new THREE.Group()
scene.add(cardGroup)
function makeGlowCard(color, x) {
  const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: .16, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide, toneMapped: false })
  const mesh = new THREE.Mesh(new THREE.PlaneGeometry(1.6, 4.8), mat)
  mesh.position.set(x, 3.3, -8.5)
  mesh.rotation.z = -.12
  cardGroup.add(mesh)
  return mesh
}
const menuCards = [makeGlowCard(0x28d8ff, -4.2), makeGlowCard(0xff3b24, 4.2)]

// Post-processing: restrained bloom for the neon and chi effects.
const composer = new EffectComposer(renderer)
composer.addPass(new RenderPass(scene, camera))
const bloom = new UnrealBloomPass(new THREE.Vector2(innerWidth, innerHeight), .62, .55, .78)
bloom.resolution.set(Math.max(320, innerWidth * .55), Math.max(200, innerHeight * .55))
composer.addPass(bloom)
composer.addPass(new OutputPass())

const MOVES = {
  punch: { kind: 'punch', startup: .095, active: .09, recovery: .18, damage: 5.4, range: 1.34, push: .18, gain: 6, label: 'STRIKE' },
  kick: { kind: 'kick', startup: .16, active: .11, recovery: .29, damage: 8.6, range: 1.72, push: .34, gain: 9, label: 'KICK' },
  palm: { kind: 'palm', startup: .32, active: .05, recovery: .47, damage: 11.5, cost: 25, range: 9, push: .45, gain: 8, special: true },
  rush: { kind: 'rush', startup: .12, active: .28, recovery: .38, damage: 15.5, cost: 40, range: 2.1, push: .6, gain: 11, special: true, dash: 7.6 },
  storm: { kind: 'storm', startup: .43, active: .24, recovery: .56, damage: 23, cost: 60, range: 1.9, push: .8, gain: 14, special: true, ultimate: true },
}

const game = {
  mode: 'menu',
  previousMode: 'fight',
  round: 1,
  wins: [0, 0],
  timer: 99,
  introTime: 0,
  introStage: 0,
  roundEndTimer: 0,
  resultTimer: 0,
  paused: false,
  hitstop: 0,
  slowmo: 0,
  shake: 0,
  shakeDecay: 0,
  time: 0,
  menuTime: 0,
  menuDemo: 3.2,
  combo: 0,
  comboTimer: 0,
  maxCombo: 0,
  chiBurned: 0,
  lastHitter: null,
  matchWinner: null,
  demoShot: 0,
}

const keys = Object.create(null)
const playerInput = { move: 0, block: false }
const ai = {
  think: .4,
  intent: 0,
  blockTimer: 0,
  cooldown: .7,
  specialTimer: 2.4,
  jumpTimer: 0,
}

function resetArenaCards() {
  menuCards.forEach((c, i) => { c.material.opacity = .16; c.position.x = i ? 4.2 : -4.2 })
}

function startMatch() {
  game.round = 1
  game.wins = [0, 0]
  game.combo = 0
  game.maxCombo = 0
  game.chiBurned = 0
  game.lastHitter = null
  game.matchWinner = null
  player.wins = 0
  enemy.wins = 0
  ui.hideResult()
  ui.setWins(game.wins)
  ui.showGame()
  startRound()
}

function startRound() {
  game.mode = 'intro'
  game.introTime = 0
  game.introStage = 0
  game.timer = 99
  game.hitstop = 0
  game.slowmo = 0
  game.combo = 0
  game.comboTimer = 0
  game.lastHitter = null
  game.roundEndTimer = 0
  ui.hideCombo()
  ui.setRound(game.round)
  ui.setTimer(game.timer)
  ui.setHealth('player', 100)
  ui.setHealth('enemy', 100)
  ui.lag = { player: 100, enemy: 100 }
  ui.setEnergy('player', 34)
  ui.setEnergy('enemy', 34)
  ui.setGuard(100)
  ui.setWins(game.wins)
  player.reset(-2.35, 1, 100)
  enemy.reset(2.35, -1, 100)
  player.energy = 34
  enemy.energy = 34
  ai.think = .55
  ai.cooldown = .45
  ai.blockTimer = 0
  ai.intent = 0
  ai.specialTimer = 2.6
  fx.clearProjectiles()
  ui.announce(`ROUND ${game.round}`, game.round === 3 ? 'FINAL ROUND' : 'FIGHT WITH HONOR', '')
  sound.bell()
  camera.position.set(-3.6, 3.8, 12.5)
}

function beginFight() {
  if (game.mode !== 'intro') return
  game.mode = 'fight'
  ui.announce('FIGHT!', '', 'special')
  sound.bell()
}

function triggerAttack(fighter, kind) {
  const move = MOVES[kind]
  if (!move || fighter.state === 'ko' || fighter.state === 'hit' || fighter.state === 'victory') return false
  if (['attack'].includes(fighter.state)) return false
  if (move.cost && fighter.energy < move.cost) {
    if (fighter === player) {
      ui.specialDenied(kind)
      sound.uiClick()
    }
    return false
  }
  if (fighter.hitStun > 0) return false
  fighter.blocking = false
  fighter.attack = { ...move, t: 0, fired: false, hit: false, announced: false }
  fighter.setState('attack', move.startup + move.active + move.recovery)
  if (move.cost) {
    fighter.energy -= move.cost
    if (fighter === player) {
      game.chiBurned += move.cost
      ui.setEnergy('player', fighter.energy)
      ui.specialActive(kind, 380)
    } else {
      ui.setEnergy('enemy', fighter.energy)
    }
    sound.charge(kind === 'storm' ? .7 : .35, kind === 'storm' ? 110 : 180)
    if (kind === 'storm') ui.flash('lightning')
  }
  if (kind === 'punch' || kind === 'kick') sound.whoosh(fighter === player ? -.3 : .3)
  return true
}

function doJump(fighter) {
  if (!fighter.grounded || fighter.state === 'ko' || fighter.state === 'attack' || fighter.state === 'hit') return
  fighter.vy = 6.4
  fighter.grounded = false
  fighter.y = .02
  sound.whoosh(fighter === player ? -.4 : .4)
}

function startMenu() {
  sound.resume()
  ui.hideBoot()
  startMatch()
}

// ── Input ─────────────────────────────────────────────────────────
function handleKey(code, down, repeat = false) {
  keys[code] = down
  if (!down) {
    if (code === 'KeyS') playerInput.block = false
    return
  }
  if (repeat) return
  if (code === 'Escape' || code === 'KeyP') {
    if (game.mode === 'menu' || game.mode === 'matchEnd') return
    togglePause()
    return
  }
  if (game.mode === 'menu') {
    if (code === 'Enter' || code === 'Space') startMenu()
    return
  }
  if (game.mode !== 'fight') return
  if (code === 'KeyW' || code === 'Space' || code === 'ShiftLeft') doJump(player)
  if (code === 'KeyJ') triggerAttack(player, 'punch')
  if (code === 'KeyK') triggerAttack(player, 'kick')
  if (code === 'KeyQ') triggerAttack(player, 'palm')
  if (code === 'KeyE') triggerAttack(player, 'rush')
  if (code === 'KeyR') triggerAttack(player, 'storm')
}

addEventListener('keydown', e => {
  const blocked = ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Space'].includes(e.code)
  if (blocked) e.preventDefault()
  handleKey(e.code, true, e.repeat)
})
addEventListener('keyup', e => handleKey(e.code, false))

function togglePause() {
  if (['menu', 'matchEnd'].includes(game.mode)) return
  if (!game.paused) {
    game.previousMode = game.mode
    game.paused = true
    game.mode = 'paused'
    ui.setPaused(true)
    sound.uiClick()
  } else {
    game.paused = false
    game.mode = game.previousMode
    ui.setPaused(false)
    sound.uiClick()
  }
}

document.getElementById('startBtn').addEventListener('click', startMenu)
document.getElementById('soundBtn').addEventListener('click', e => {
  const on = e.currentTarget.classList.toggle('is-muted') === false
  sound.setEnabled(on)
  e.currentTarget.setAttribute('aria-pressed', String(on))
  sound.resume()
})
document.getElementById('pauseBtn').addEventListener('click', togglePause)
document.getElementById('resumeBtn').addEventListener('click', togglePause)
document.getElementById('restartBtn').addEventListener('click', () => {
  game.paused = false
  game.mode = 'fight'
  ui.setPaused(false)
  startMatch()
})
document.getElementById('quitBtn').addEventListener('click', () => {
  game.paused = false
  game.mode = 'menu'
  ui.setPaused(false)
  ui.showMenu()
  resetFightersForMenu()
})
document.getElementById('rematchBtn').addEventListener('click', () => {
  sound.uiClick()
  startMatch()
})
document.getElementById('titleBtn').addEventListener('click', () => {
  game.mode = 'menu'
  ui.showMenu()
  resetFightersForMenu()
})
document.getElementById('pauseOverlay').addEventListener('click', e => {
  if (e.target === e.currentTarget) togglePause()
})

function resetFightersForMenu() {
  player.reset(-2.35, 1, 100)
  enemy.reset(2.35, -1, 100)
  player.state = 'idle'
  enemy.state = 'idle'
  fx.clearProjectiles()
  game.combo = 0
  ui.hideCombo()
  ui.showMenu()
}

// Touch controls.
for (const btn of document.querySelectorAll('[data-key]')) {
  const code = btn.dataset.key
  const press = e => {
    e.preventDefault()
    btn.classList.add('is-down')
    handleKey(code, true)
  }
  const release = e => {
    e.preventDefault()
    btn.classList.remove('is-down')
    handleKey(code, false)
  }
  btn.addEventListener('pointerdown', press)
  btn.addEventListener('pointerup', release)
  btn.addEventListener('pointercancel', release)
  btn.addEventListener('pointerleave', e => { if (e.buttons) release(e) })
  btn.addEventListener('contextmenu', e => e.preventDefault())
}

addEventListener('blur', () => {
  for (const k of Object.keys(keys)) keys[k] = false
  playerInput.block = false
  if (game.mode === 'fight') {
    game.previousMode = game.mode
    game.paused = true
    game.mode = 'paused'
    ui.setPaused(true)
  }
})

